SELECT p.product_id, p.name, SUM(oi.line_total_bdt) AS gmv FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN product_variants v ON v.variant_id = oi.variant_id JOIN products p ON p.product_id = v.product_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-07-01' AND DATE '2024-09-30' AND p.name IN (SELECT name FROM products GROUP BY name HAVING COUNT(*) > 1) GROUP BY p.product_id, p.name ORDER BY gmv DESC, p.product_id LIMIT 5
